                @All_Jurisdictions_Fl,
                @All_Trans_Src_Fl,
                @Look_Back_Period,
                @Frequency_Period,
                @HR_Min_Indiv_Trans_Amt,
                @RR_Min_Indiv_Trans_Amt,
                @HR_Same_Amt_Range,
                @RR_Same_Amt_Range,
                @Include_B2B_Trnfr_Fl,
                @Curr_Type)) b,
       Incld_Accts a,
       Incld_Occrs o

  WHERE  
           b.ACCT_INTRL_ID = a.ACCT_INTRL_ID      
       and a.ACCT_INTRL_ID = o.ACCT_INTRL_ID
       and b.OCC_NB = o.OCC_NB

with Incld_Occrs as
