                @MINER@.Lst(@Incl_Jurisdictions_Lst),
                @MINER@.Lst(@Incl_Trans_Src_Lst),
                @Incl_Rltd_Parties,
                @Include_Trusted_Trans_FL,
                @MINER@.Lst(@Mantas_Bus_Acct_Type_Lst),
                @All_Jurisdictions_Fl,
                @All_Trans_Src_Fl,
                @Look_Back_Period,
                @Frequency_Period,
                @HR_Min_Indiv_Trans_Amt,
                @RR_Min_Indiv_Trans_Amt,
                @HR_Same_Amt_Range,
                @RR_Same_Amt_Range,
                @Curr_Type)) a
   GROUP BY  a.ACCT_INTRL_ID, a.ACCT_SEQ_ID, a.ACCT_EFCTV_RISK_NB, a.OCC_NB
   HAVING 
       (
		   (a.ACCT_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl 
          and max(a.TOT_TRXN_CT) >= @HR_Min_Trans_Ct
          and max(a.TOT_TRXN_AMT) >= @HR_Min_Trans_Amt
       )   
		   or
		   (a.ACCT_EFCTV_RISK_NB < @Effctv_Risk_Cutoff_Lvl  
          and max(a.TOT_TRXN_CT) >= @RR_Min_Trans_Ct
          and max(a.TOT_TRXN_AMT) >= @RR_Min_Trans_Amt
       )
	     )
),

Incld_Accts as
(SELECT 
       p.ACCT_INTRL_ID, 
       p.ACCT_EFCTV_RISK_NB,  
       count(distinct p.OCC_NB) as Occ_Ct

FROM 
     Incld_Occrs p 
GROUP BY  
      p.ACCT_INTRL_ID, p.ACCT_EFCTV_RISK_NB
HAVING 
            (
		        (p.ACCT_EFCTV_RISK_NB >= @Effctv_Risk_Cutoff_Lvl and count(distinct p.OCC_NB) >= @HR_Min_Occurrence_Ct)
		          or
		        (p.ACCT_EFCTV_RISK_NB < @Effctv_Risk_Cutoff_Lvl  and count(distinct p.OCC_NB) >= @RR_Min_Occurrence_Ct)
	          )   
        AND max(p.Data_Dump_Dt_Max) in (select b.CLNDR_DT from @MANTAS@.KDD_cal b where b.CLNDR_NM = 'SYSCAL' and b.CLNDR_DAY_AGE between 0 and @Frequency_Period - 1)  
)

--Transactions
SELECT 

       a.ACCT_INTRL_ID,
       b.FO_TRXN_SEQ_ID

  FROM 
     TABLE(@MINER@.DEPWD_AC_DEP_CASH_PIPELINE(
                @Lrf_Digits,
                @Effctv_Risk_Cutoff_Lvl,
                @MINER@.Lst(@Incl_Cash_Trxn_Prdct_Type_Lst),
                @MINER@.Lst(@Incl_Jurisdictions_Lst),
                @MINER@.Lst(@Incl_Trans_Src_Lst),
                @Incl_Rltd_Parties,
                @Include_Trusted_Trans_FL,
                @MINER@.Lst(@Mantas_Bus_Acct_Type_Lst),
                @All_Jurisdictions_Fl,
                @All_Trans_Src_Fl,
                @Look_Back_Period,
                @Frequency_Period,
                @HR_Min_Indiv_Trans_Amt,
                @RR_Min_Indiv_Trans_Amt,
                @HR_Same_Amt_Range,
                @RR_Same_Amt_Range,
                @Curr_Type)) b,
       Incld_Accts a,
       Incld_Occrs o

  WHERE  
           b.ACCT_INTRL_ID = a.ACCT_INTRL_ID      
       and a.ACCT_INTRL_ID = o.ACCT_INTRL_ID
       and b.OCC_NB = o.OCC_NB
